describe('Form Submission with Confirmation Email', () => {
  beforeEach(() => {
    cy.visit('/contact-form');
  });

  it('should successfully submit form and send confirmation email', () => {
    // Intercept the API call to submit the form
    cy.intercept('POST', '/api/contact-form').as('formSubmit');

    // Fill in the form fields
    cy.get('[data-testid="name-input"]').type('John Doe');
    cy.get('[data-testid="email-input"]').type('john.doe@example.com');
    cy.get('[data-testid="message-textarea"]').type('Hello, I am interested in your product.');

    // Verify all fields are filled
    cy.get('[data-testid="name-input"]').should('have.value', 'John Doe');
    cy.get('[data-testid="email-input"]').should('have.value', 'john.doe@example.com');
    cy.get('[data-testid="message-textarea"]').should('have.value', 'Hello, I am interested in your product.');

    // Submit the form
    cy.get('[data-testid="submit-button"]').click();

    // Wait for the API call to complete
    cy.wait('@formSubmit');

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Thank you for your message');

    // Verify confirmation email was sent
    cy.get('[data-testid="email-confirmation-toast"]').should('be.visible');
    cy.get('[data-testid="email-confirmation-toast"]').should('contain', 'Your email has been sent');

    // Verify email was sent to the correct address
    cy.get('[data-testid="email-confirmation-toast"]').should('contain', 'john.doe@example.com');
  });

  it('should handle form submission failure and display error message', () => {
    // Intercept the API call to submit the form
    cy.intercept('POST', '/api/contact-form', {
      statusCode: 500,
      body: { error: 'Internal server error' }
    }).as('formSubmitError');

    // Fill in the form fields
    cy.get('[data-testid="name-input"]').type('Jane Smith');
    cy.get('[data-testid="email-input"]').type('jane.smith@example.com');
    cy.get('[data-testid="message-textarea"]').type('Please help, my order is delayed.');

    // Submit the form
    cy.get('[data-testid="submit-button"]').click();

    // Wait for the API call to complete
    cy.wait('@formSubmitError');

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Failed to send your message');

    // Verify success message does not appear
    cy.get('[data-testid="success-message"]').should('not.exist');

    // Verify email was not sent
    cy.get('[data-testid="email-confirmation-toast"]').should('not.exist');
  });
});
